/**
 * Git Pre-Push Hook Installer
 * Automatically configures a pre-push hook to block commits/pushes containing P0 Critical Blockers.
 */

const fs = require('fs');
const path = require('path');

const HOOK_SCRIPT = `#!/bin/sh
# LaunchGate Production Preflight Gatekeeper
# Automatically generated by LaunchGate

echo ""
echo "🔍 [LaunchGate] Executing pre-push production readiness audit..."

# Run LaunchGate in CI/fail-on-p0 mode
if command -v launchgate >/dev/null 2>&1; then
  launchgate scan --fail-on-p0
elif [ -f "./cli.js" ]; then
  node ./cli.js scan --fail-on-p0
elif [ -f "../cli.js" ]; then
  node ../cli.js scan --fail-on-p0
else
  npx launchgate scan --fail-on-p0
fi

STATUS=$?
if [ $STATUS -ne 0 ]; then
  echo ""
  echo "❌ [LaunchGate] GIT PUSH ABORTED: P0 Critical Blockers detected!"
  echo "👉 Resolve issues or run 'npx launchgate' to open the command center."
  echo ""
  exit 1
fi

echo "✅ [LaunchGate] Preflight verified: zero P0 blockers. Proceeding with push..."
echo ""
exit 0
`;

function installGitHook(projectPath) {
  const gitDir = path.join(projectPath, '.git');
  if (!fs.existsSync(gitDir)) {
    return {
      success: false,
      error: 'Not a Git repository (.git directory not found).'
    };
  }

  const hooksDir = path.join(gitDir, 'hooks');
  if (!fs.existsSync(hooksDir)) {
    fs.mkdirSync(hooksDir, { recursive: true });
  }

  const hookFile = path.join(hooksDir, 'pre-push');
  fs.writeFileSync(hookFile, HOOK_SCRIPT, { mode: 0o755 });

  // If Husky is present, also write to .husky/pre-push
  const huskyDir = path.join(projectPath, '.husky');
  if (fs.existsSync(huskyDir)) {
    const huskyHook = path.join(huskyDir, 'pre-push');
    fs.writeFileSync(huskyHook, HOOK_SCRIPT, { mode: 0o755 });
  }

  return {
    success: true,
    hookPath: path.relative(projectPath, hookFile),
    message: 'Git pre-push hook installed successfully! Pushes will now be blocked if P0 issues exist.'
  };
}

module.exports = {
  installGitHook,
  HOOK_SCRIPT
};
